function validate([s, t]) {
  if (s.length < 1 || s.length > 30) return 's needs 1 to 30 letters.';
  if (t.length < 1 || t.length > 30) return 't needs 1 to 30 letters.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(t)) return 's and t use only lowercase English letters.';
  return null;
}

