function longestPalindrome(s, t) {
  const isPalindrome = (text) => {
    let left = 0;
    let right = text.length - 1;
    while (left < right) {
      if (text[left] !== text[right]) {
        return false;
      }
      left++;
      right--;
    }
    return true;
  };
  let best = 0;
  for (let sStart = 0; sStart <= s.length; sStart++) {
    for (let sEnd = sStart; sEnd <= s.length; sEnd++) {
      const front = s.slice(sStart, sEnd);
      for (let tStart = 0; tStart <= t.length; tStart++) {
        for (let tEnd = tStart; tEnd <= t.length; tEnd++) {
          const candidate = front + t.slice(tStart, tEnd);
          if (candidate.length > best && isPalindrome(candidate)) {
            best = candidate.length;
          }
        }
      }
    }
  }
  return best;
}

