function longestPalindrome(s, t) {
  // Try every total length from the largest down; the first one that works is the answer.
  for (let total = s.length + t.length; total > 0; total--) {
    for (let fromS = 0; fromS <= Math.min(total, s.length); fromS++) {
      const fromT = total - fromS;
      if (fromT > t.length) continue;
      for (let a = 0; a + fromS <= s.length; a++) {
        for (let b = 0; b + fromT <= t.length; b++) {
          const joined = s.substr(a, fromS) + t.substr(b, fromT);
          if (joined === joined.split('').reverse().join('')) return total;
        }
      }
    }
  }
  return 0;
}

