function generate(rand, size) {
  const large = size === 'large';
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.slice(0, large ? pick(1, 26) : pick(1, 3));
  const word = (length) => Array.from({ length }, () => alphabet[pick(0, alphabet.length - 1)]).join('');
  const mirror = (text) => [...text].reverse().join('');
  const limit = large ? 30 : 6;
  const length = (least) => (large ? limit : pick(Math.max(1, least), limit));
  if (rand() < 0.4) return [word(length(1)), word(length(1))];
  // Plant a piece in s, a palindrome next to it in s or t, and the piece's mirror image in t, so long answers appear.
  const outer = word(pick(0, large ? 10 : 2));
  const half = word(pick(0, large ? 5 : 1));
  const palindrome = half + (rand() < 0.5 ? word(1) : '') + mirror(half);
  const inS = rand() < 0.5;
  const coreS = outer + (inS ? palindrome : '');
  const coreT = (inS ? '' : palindrome) + mirror(outer);
  const pad = (core) => {
    const total = length(core.length);
    const before = pick(0, total - core.length);
    return word(before) + core + word(total - core.length - before);
  };
  return [pad(coreS), pad(coreT)];
}
